package io.knowledgebrain.learning;
import java.util.*;
import java.time.*;
import jakarta.servlet.http.Cookie;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;

class LearningStudyApiTest {
 LearningStudyStore store;SpaceAuthorizationClient auth;LearningStudyController api;UUID space,roadmap,node,actor;
 @BeforeEach void setup(){var ids=new UuidV7(Clock.systemUTC());space=ids.next();roadmap=ids.next();node=ids.next();actor=ids.next();store=mock(LearningStudyStore.class);auth=mock(SpaceAuthorizationClient.class);when(auth.authorize(eq(space),any(),anyBoolean(),anyString())).thenReturn(actor);var metrics=new SimpleMeterRegistry();api=new LearningStudyController(store,new RoadmapController(mock(RoadmapStore.class),auth,metrics,"https://localhost:8443"),metrics);}
 MockHttpServletRequest r(String method,String body){var r=new MockHttpServletRequest(method,"/api/spaces/"+space+"/roadmaps/"+roadmap+"/learning");r.setSecure(true);r.setCookies(new Cookie("__Host-brain_guest","a".repeat(43)));r.addHeader("Origin","https://localhost:8443");r.setContentType("application/json");if(body!=null)r.setContent(body.getBytes(java.nio.charset.StandardCharsets.UTF_8));return r;}
 @Test void everyReadUsesFreshSpaceAuthorityAndNoStoreBeforeCanonicalAccess(){when(store.summary(space,roadmap)).thenReturn(new LearningStudyStore.Summary(roadmap,space,1,List.of(),0,0,0,0,0));assertEquals("no-store",api.summary(space.toString(),roadmap.toString(),r("GET",null)).getHeaders().getCacheControl());api.summary(space.toString(),roadmap.toString(),r("GET",null));verify(auth,times(2)).authorize(eq(space),eq("a".repeat(43)),eq(false),anyString());reset(store);when(auth.authorize(eq(space),any(),anyBoolean(),anyString())).thenThrow(new ResponseStatusException(HttpStatus.NOT_FOUND));assertThrows(ResponseStatusException.class,()->api.summary(space.toString(),roadmap.toString(),r("GET",null)));verifyNoInteractions(store);}
 @Test void progressRequiresIndependentStrongEtagAndStrictOneFieldJson()throws Exception{for(String tag:List.of("\"rm1\"","\"ss1\"","W/\"pr1\"","\"pr01\"","*","\"pr9223372036854775808\"")){var r=r("PUT","{\"status\":\"COMPLETED\"}");r.addHeader("If-Match",tag);assertThrows(ResponseStatusException.class,()->api.writeProgress(space.toString(),roadmap.toString(),node.toString(),r));}var missing=r("PUT","{}");assertEquals(428,assertThrows(ResponseStatusException.class,()->api.writeProgress(space.toString(),roadmap.toString(),node.toString(),missing)).getStatusCode().value());for(String body:List.of("{\"status\":\"COMPLETED\",\"actorId\":\"spoof\"}","{\"status\":\"COMPLETED\",\"status\":\"IN_PROGRESS\"}","{\"status\":\"COMPLETED\"} {}","{}")){var r=r("PUT",body);r.addHeader("If-Match","\"pr0\"");assertThrows(ResponseStatusException.class,()->api.writeProgress(space.toString(),roadmap.toString(),node.toString(),r));}verifyNoInteractions(store);}
 @Test void sessionReplayRequiresSingleOpaqueRequestKeyAndDoesNotAcceptClientSessionIds()throws Exception{String body="{\"nodeId\":\""+node+"\",\"startedAt\":\"2026-10-15T08:00:00Z\",\"endedAt\":\"2026-10-15T08:01:00Z\",\"note\":\"\"}";var noKey=r("POST",body);assertThrows(ResponseStatusException.class,()->api.record(space.toString(),roadmap.toString(),noKey));var wrong=r("POST",body);wrong.addHeader("Idempotency-Key","client-session");assertThrows(ResponseStatusException.class,()->api.record(space.toString(),roadmap.toString(),wrong));var extra=r("POST",body.substring(0,body.length()-1)+",\"sessionId\":\"client\"}");extra.addHeader("Idempotency-Key","b".repeat(32));assertThrows(ResponseStatusException.class,()->api.record(space.toString(),roadmap.toString(),extra));var cross=r("POST",body);cross.removeHeader("Origin");cross.addHeader("Origin","https://foreign.invalid");assertEquals(403,assertThrows(ResponseStatusException.class,()->api.record(space.toString(),roadmap.toString(),cross)).getStatusCode().value());verifyNoInteractions(store);}
 @Test void invalidQueriesAndGetBodyFailBeforeAuthority(){var body=r("GET","{}");assertThrows(ResponseStatusException.class,()->api.summary(space.toString(),roadmap.toString(),body));var dup=r("GET",null);dup.addParameter("limit","1","2");assertThrows(ResponseStatusException.class,()->api.sessions(space.toString(),roadmap.toString(),dup));var query=r("GET",null);query.addParameter("limit","11");assertThrows(ResponseStatusException.class,()->api.progressHistory(space.toString(),roadmap.toString(),node.toString(),query));verifyNoInteractions(store,auth);}
 @Test void httpVersionErrorsRetainTheirStatusAndPrivacyHeaders()throws Exception{var mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup(api).setControllerAdvice(new RoadmapErrors()).build();mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put("/api/spaces/"+space+"/roadmaps/"+roadmap+"/nodes/"+node+"/progress").secure(true).cookie(new Cookie("__Host-brain_guest","a".repeat(43))).header("Origin","https://localhost:8443").contentType("application/json").content("{\"status\":\"COMPLETED\"}")).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.status().is(428)).andExpect(org.springframework.test.web.servlet.result.MockMvcResultMatchers.header().string("Cache-Control","no-store"));verifyNoInteractions(store);}
}
